const patchWbCard = `-- name: PatchWbCard :exec
UPDATE wb_cards
SET x = coalesce($1, x),
    y = coalesce($2, y),
    w = coalesce($3, w),
    h = coalesce($4, h),
    z = coalesce($5, z),
    color = CASE WHEN $6::bool THEN NULL ELSE coalesce($7, color) END,
    content = coalesce($8, content),
    plain = coalesce($9, plain),
    content_version = content_version + CASE WHEN $8::jsonb IS NULL THEN 0 ELSE 1 END,
    version = version + 1,
    seq = $10,
    updated_by = $11
WHERE id = $12 AND board_id = $13 AND deleted_at IS NULL
`

type PatchWbCardParams struct {
	X          pgtype.Float8
	Y          pgtype.Float8
	W          pgtype.Float8
	H          pgtype.Float8
	Z          pgtype.Float8
	ClearColor bool
	Color      pgtype.Text
	Content    []byte
	Plain      pgtype.Text
	Seq        int64
	ActorID    int64
	ID         pgtype.UUID
	BoardID    pgtype.UUID
}

// Hanya field yang dikirim yang berubah (last-write-wins per field). Warna dikosongkan lewat clear_color, karena
// NULL pada sqlc.narg berarti "tidak diubah".
func (q *Queries) PatchWbCard(ctx context.Context, arg PatchWbCardParams) error {
	_, err := q.db.Exec(ctx, patchWbCard,
		arg.X,
		arg.Y,
		arg.W,
		arg.H,
		arg.Z,
		arg.ClearColor,
		arg.Color,
		arg.Content,
		arg.Plain,
		arg.Seq,
		arg.ActorID,
		arg.ID,
		arg.BoardID,
	)
	return err
}

