const trashWbSubtree = `-- name: TrashWbSubtree :many
WITH RECURSIVE sub AS (
  SELECT b.id FROM wb_boards b WHERE b.id = ANY($3::uuid[]) AND b.deleted_at IS NULL AND NOT b.is_root
  UNION ALL
  SELECT c.id FROM wb_boards c JOIN sub ON c.parent_id = sub.id WHERE c.deleted_at IS NULL
)
UPDATE wb_boards
SET deleted_at = now(), deleted_by = $1::bigint, deleted_batch = $2, updated_by = $1
WHERE id IN (SELECT id FROM sub)
RETURNING id, title
`

